-- Permission vocabulary and system roles of the project module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the project permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('activity_type:create'::text, 'activity_type'::text, 'create'::text, 'Create activity type'::text),
            ('activity_type:delete'::text, 'activity_type'::text, 'delete'::text, 'Delete activity type'::text),
            ('activity_type:purge'::text, 'activity_type'::text, 'purge'::text, 'Purge activity type'::text),
            ('activity_type:read'::text, 'activity_type'::text, 'read'::text, 'Read activity type'::text),
            ('activity_type:restore'::text, 'activity_type'::text, 'restore'::text, 'Restore activity type'::text),
            ('activity_type:update'::text, 'activity_type'::text, 'update'::text, 'Update activity type'::text),
            ('project:create'::text, 'project'::text, 'create'::text, 'Create project'::text),
            ('project:delete'::text, 'project'::text, 'delete'::text, 'Delete project'::text),
            ('project:purge'::text, 'project'::text, 'purge'::text, 'Purge project'::text),
            ('project:read'::text, 'project'::text, 'read'::text, 'Read project'::text),
            ('project:restore'::text, 'project'::text, 'restore'::text, 'Restore project'::text),
            ('project:update'::text, 'project'::text, 'update'::text, 'Update project'::text),
            ('project_template:create'::text, 'project_template'::text, 'create'::text, 'Create project template'::text),
            ('project_template:delete'::text, 'project_template'::text, 'delete'::text, 'Delete project template'::text),
            ('project_template:purge'::text, 'project_template'::text, 'purge'::text, 'Purge project template'::text),
            ('project_template:read'::text, 'project_template'::text, 'read'::text, 'Read project template'::text),
            ('project_template:restore'::text, 'project_template'::text, 'restore'::text, 'Restore project template'::text),
            ('project_template:update'::text, 'project_template'::text, 'update'::text, 'Update project template'::text),
            ('project_template_task:create'::text, 'project_template_task'::text, 'create'::text, 'Create project template task'::text),
            ('project_template_task:delete'::text, 'project_template_task'::text, 'delete'::text, 'Delete project template task'::text),
            ('project_template_task:purge'::text, 'project_template_task'::text, 'purge'::text, 'Purge project template task'::text),
            ('project_template_task:read'::text, 'project_template_task'::text, 'read'::text, 'Read project template task'::text),
            ('project_template_task:restore'::text, 'project_template_task'::text, 'restore'::text, 'Restore project template task'::text),
            ('project_template_task:update'::text, 'project_template_task'::text, 'update'::text, 'Update project template task'::text),
            ('task:create'::text, 'task'::text, 'create'::text, 'Create task'::text),
            ('task:delete'::text, 'task'::text, 'delete'::text, 'Delete task'::text),
            ('task:purge'::text, 'task'::text, 'purge'::text, 'Purge task'::text),
            ('task:read'::text, 'task'::text, 'read'::text, 'Read task'::text),
            ('task:restore'::text, 'task'::text, 'restore'::text, 'Restore task'::text),
            ('task:update'::text, 'task'::text, 'update'::text, 'Update task'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('activity_type:create'::text, 'activity_type'::text, 'create'::text, 'Create activity type'::text),
            ('activity_type:delete'::text, 'activity_type'::text, 'delete'::text, 'Delete activity type'::text),
            ('activity_type:purge'::text, 'activity_type'::text, 'purge'::text, 'Purge activity type'::text),
            ('activity_type:read'::text, 'activity_type'::text, 'read'::text, 'Read activity type'::text),
            ('activity_type:restore'::text, 'activity_type'::text, 'restore'::text, 'Restore activity type'::text),
            ('activity_type:update'::text, 'activity_type'::text, 'update'::text, 'Update activity type'::text),
            ('project:create'::text, 'project'::text, 'create'::text, 'Create project'::text),
            ('project:delete'::text, 'project'::text, 'delete'::text, 'Delete project'::text),
            ('project:purge'::text, 'project'::text, 'purge'::text, 'Purge project'::text),
            ('project:read'::text, 'project'::text, 'read'::text, 'Read project'::text),
            ('project:restore'::text, 'project'::text, 'restore'::text, 'Restore project'::text),
            ('project:update'::text, 'project'::text, 'update'::text, 'Update project'::text),
            ('project_template:create'::text, 'project_template'::text, 'create'::text, 'Create project template'::text),
            ('project_template:delete'::text, 'project_template'::text, 'delete'::text, 'Delete project template'::text),
            ('project_template:purge'::text, 'project_template'::text, 'purge'::text, 'Purge project template'::text),
            ('project_template:read'::text, 'project_template'::text, 'read'::text, 'Read project template'::text),
            ('project_template:restore'::text, 'project_template'::text, 'restore'::text, 'Restore project template'::text),
            ('project_template:update'::text, 'project_template'::text, 'update'::text, 'Update project template'::text),
            ('project_template_task:create'::text, 'project_template_task'::text, 'create'::text, 'Create project template task'::text),
            ('project_template_task:delete'::text, 'project_template_task'::text, 'delete'::text, 'Delete project template task'::text),
            ('project_template_task:purge'::text, 'project_template_task'::text, 'purge'::text, 'Purge project template task'::text),
            ('project_template_task:read'::text, 'project_template_task'::text, 'read'::text, 'Read project template task'::text),
            ('project_template_task:restore'::text, 'project_template_task'::text, 'restore'::text, 'Restore project template task'::text),
            ('project_template_task:update'::text, 'project_template_task'::text, 'update'::text, 'Update project template task'::text),
            ('task:create'::text, 'task'::text, 'create'::text, 'Create task'::text),
            ('task:delete'::text, 'task'::text, 'delete'::text, 'Delete task'::text),
            ('task:purge'::text, 'task'::text, 'purge'::text, 'Purge task'::text),
            ('task:read'::text, 'task'::text, 'read'::text, 'Read task'::text),
            ('task:restore'::text, 'task'::text, 'restore'::text, 'Restore task'::text),
            ('task:update'::text, 'task'::text, 'update'::text, 'Update task'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
